<!-- Persistent chrome for vodafone-pt-digital. Slidev registers it by filename.

     It emits three things. The STAGE (the dark gradient, the drifting glows, the red
     grids, the rising particles, the vignette), painted once and UNDER every slide:
     style.css puts it at z-index -1 inside the slide container and keeps the layout
     transparent, so it never travels with a slide transition. The LOCKUP top-left
     (speechmark tile, divider, "Digital Engineering" over "VODAFONE PORTUGAL", the
     Portuguese flag) on every page but the close, the cover included, as the shell has
     it. The HEAD top-right (deck title over section and page number) and the LEGAL line
     bottom-left, on every page that is neither a cover nor bare.

     A page's frontmatter `class` drives it: `vfd-cover` keeps the lockup and drops the
     head and legal line; `vfd-bare` drops all chrome; `vfd-close` (with vfd-bare) adds
     the speechmark in the middle of the red field, since the chrome is what holds the
     tile. The tile and the flag are embedded here so the identity renders even when
     a deck's public/ was never populated; public/ in the theme holds the same marks
     for use inside pages.

     The slide is read from the slide context's nav, not from the shared useNav(): in
     print and export Slidev renders every page with its own fixed nav while the shared
     one stays on slide 1, which is the export defect earlier Vodafone decks carried
     (every exported page lost its header). Set the three constants below; nothing else
     here needs editing. -->
<template>
  <div>
    <div class="vfd-stage" aria-hidden="true">
      <div class="vfd-glow vfd-glow--a"></div>
      <div class="vfd-glow vfd-glow--b"></div>
      <div class="vfd-glow vfd-glow--c"></div>
      <div class="vfd-grid"></div>
      <div class="vfd-particles">
        <span v-for="n in 18" :key="n" class="vfd-particle"></span>
      </div>
      <div class="vfd-vignette"></div>
    </div>

    <div v-if="!isBare" class="vfd-lockup">
      <img class="vfd-tile" :src="TILE" alt="" />
      <span class="vfd-lockup-div"></span>
      <span class="vfd-lockup-text">
        <span class="vfd-lockup-l1">{{ UNIT }}</span>
        <span class="vfd-lockup-l2">{{ ORG }}</span>
      </span>
      <svg class="vfd-flag" viewBox="0 0 28 19" aria-hidden="true">
        <clipPath id="vfd-flag-clip"><rect width="28" height="19" rx="3" /></clipPath>
        <g clip-path="url(#vfd-flag-clip)">
          <rect class="vfd-flag-green" width="11.8" height="19" />
          <rect class="vfd-flag-red" x="11.8" width="16.2" height="19" />
        </g>
        <circle class="vfd-flag-sphere" cx="11.8" cy="9.5" r="5.7" />
        <ellipse class="vfd-flag-ring" cx="11.8" cy="9.5" rx="5.7" ry="2.39" />
        <ellipse class="vfd-flag-ring" cx="11.8" cy="9.5" rx="2.39" ry="5.7" />
        <line class="vfd-flag-axis" x1="6.1" y1="9.5" x2="17.5" y2="9.5" />
        <rect class="vfd-flag-shield" x="9.34" y="6.7" width="4.92" height="5.81" rx="1" />
        <circle class="vfd-flag-dot" cx="11.8" cy="9.67" r="1.03" />
        <rect class="vfd-flag-edge" width="28" height="19" rx="3" />
      </svg>
    </div>

    <div v-if="!isCover && !isBare" class="vfd-head">
      <div class="vfd-head-title">Presentation title</div>
      <div class="vfd-head-meta">
        <span v-if="section" class="vfd-head-section">{{ section }}</span>
        <span class="vfd-head-num">{{ pageLabel }}</span>
      </div>
    </div>

    <div v-if="!isCover && !isBare" class="vfd-legal">
      <span class="vfd-legal-mark"></span>
      <span>{{ LEGAL }}</span>
    </div>

    <img v-if="isClose" class="vfd-close-mark" :src="TILE" alt="" />
  </div>
</template>

<script setup>
import { computed, unref } from 'vue'
import { useSlideContext } from '@slidev/client'

const UNIT = 'Digital Engineering'
const ORG = 'VODAFONE PORTUGAL'
const LEGAL = 'Vodafone Portugal · Digital Engineering · Confidential'

// The speechmark tile (public/vf-tile-50.png in the theme), embedded so the lockup
// never depends on a file under the deck's public/.
const TILE = 'data:image/png;base64,'

// The slide context's nav is the per-slide fixed nav while printing and the live nav
// while presenting; the shared useNav() is only ever the latter.
const { $slidev } = useSlideContext()

const route = computed(() => unref($slidev.nav.currentSlideRoute))
const frontmatter = computed(() => route.value?.meta?.slide?.frontmatter ?? {})
const classes = computed(() => String(frontmatter.value.class ?? ''))
const isCover = computed(() => classes.value.includes('vfd-cover'))
const isBare = computed(() => classes.value.includes('vfd-bare'))
const isClose = computed(() => classes.value.includes('vfd-close'))
const section = computed(() => frontmatter.value.section ?? '')
const pageLabel = computed(() => String(unref($slidev.nav.currentPage) ?? '').padStart(2, '0'))
</script>
